import{_ as t,o as i,c as s,aj as a}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Setting up HttpClient","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/http/setup.md","filePath":"en/guide/http/setup.md"}'),n={name:"en/guide/http/setup.md"};function o(r,e,d,p,h,l){return i(),s("div",null,e[0]||(e[0]=[a('<h1 id="setting-up-httpclient" tabindex="-1">Setting up <code>HttpClient</code> <a class="header-anchor" href="#setting-up-httpclient" aria-label="Permalink to &quot;Setting up `HttpClient`&quot;">​</a></h1><p><code>HttpClient</code> is available for injection by default in Angular v21 and later.</p><h2 id="providing-httpclient-through-dependency-injection" tabindex="-1">Providing <code>HttpClient</code> through dependency injection <a class="header-anchor" href="#providing-httpclient-through-dependency-injection" aria-label="Permalink to &quot;Providing `HttpClient` through dependency injection&quot;">​</a></h2><p>You can use the <code>provideHttpClient</code> helper function to configure the default HTTP feature set or add features in the application <code>providers</code> in <code>app.config.ts</code>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> appConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ApplicationConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  providers: [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provideHttpClient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* add features here, such as withInterceptors(...) */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)],</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>If your app is using NgModule-based bootstrap instead, you can include <code>provideHttpClient</code> in the providers of your app&#39;s NgModule to configure the default HTTP feature set or add features:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">NgModule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  providers: [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provideHttpClient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* add features here, such as withInterceptors(...) */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)],</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // ... other application configuration</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AppModule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}</span></span></code></pre></div><p>You can then inject the <code>HttpClient</code> service as a dependency of your components, services, or other classes:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ConfigService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  private</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> http</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> inject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(HttpClient);</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // This service can now make HTTP requests via `this.http`.</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="configuring-features-of-httpclient" tabindex="-1">Configuring features of <code>HttpClient</code> <a class="header-anchor" href="#configuring-features-of-httpclient" aria-label="Permalink to &quot;Configuring features of `HttpClient`&quot;">​</a></h2><p><code>provideHttpClient</code> accepts a list of optional feature configurations to enable or configure different aspects of the client. This section details the optional features and their usage.</p><h3 id="withxhr" tabindex="-1"><code>withXhr</code> <a class="header-anchor" href="#withxhr" aria-label="Permalink to &quot;`withXhr`&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> appConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ApplicationConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  providers: [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provideHttpClient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withXhr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())],</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>By default, <code>HttpClient</code> uses the <a href="https://developer.mozilla.org/docs/Web/API/Fetch_API" target="_blank" rel="noreferrer"><code>fetch</code></a> API to make requests. The <code>withXhr</code> feature switches the client to use the <a href="https://developer.mozilla.org/docs/Web/API/XMLHttpRequest" target="_blank" rel="noreferrer"><code>XMLHttpRequest</code></a> API instead.</p><p><code>fetch</code> is a more modern API and is available in a few environments where <code>XMLHttpRequest</code> is not supported. It does have a few limitations, such as not producing upload progress events.</p><div class="danger custom-block"><p class="custom-block-title">Do not use <code>withXhr</code> in server-side rendering (SSR) environments</p><p>XHR support on the server is <strong>deprecated</strong> and is intended to be removed in Angular 23. The underlying <code>xhr2</code> library does not safely handle redirects: it can forward <code>Authorization</code> headers on cross-origin redirects and is susceptible to denial-of-service (DoS) via redirect loops. For SSR applications, use the default <code>fetch</code> backend instead.</p></div><h3 id="withinterceptors" tabindex="-1"><code>withInterceptors(...)</code> <a class="header-anchor" href="#withinterceptors" aria-label="Permalink to &quot;`withInterceptors(...)`&quot;">​</a></h3><p><code>withInterceptors</code> configures the set of interceptor functions which will process requests made through <code>HttpClient</code>. See the <a href="/en/guide/http/interceptors">interceptor guide</a> for more information.</p><h3 id="withinterceptorsfromdi" tabindex="-1"><code>withInterceptorsFromDi()</code> <a class="header-anchor" href="#withinterceptorsfromdi" aria-label="Permalink to &quot;`withInterceptorsFromDi()`&quot;">​</a></h3><p><code>withInterceptorsFromDi</code> includes the older style of class-based interceptors in the <code>HttpClient</code> configuration. See the <a href="/en/guide/http/interceptors">interceptor guide</a> for more information.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>Functional interceptors (through <code>withInterceptors</code>) have more predictable ordering and we recommend them over DI-based interceptors.</p></div><h3 id="withrequestsmadeviaparent" tabindex="-1"><code>withRequestsMadeViaParent()</code> <a class="header-anchor" href="#withrequestsmadeviaparent" aria-label="Permalink to &quot;`withRequestsMadeViaParent()`&quot;">​</a></h3><p>By default, when you configure <code>HttpClient</code> using <code>provideHttpClient</code> within a given injector, this configuration overrides any configuration for <code>HttpClient</code> which may be present in the parent injector.</p><p>When you add <code>withRequestsMadeViaParent()</code>, <code>HttpClient</code> is configured to instead pass requests up to the <code>HttpClient</code> instance in the parent injector, once they&#39;ve passed through any configured interceptors at this level. This is useful if you want to <em>add</em> interceptors in a child injector while still sending the request through the parent injector&#39;s interceptors.</p><div class="danger custom-block"><p class="custom-block-title">CRITICAL</p><p>You must configure an instance of <code>HttpClient</code> above the current injector, or this option is not valid and you&#39;ll get a runtime error when you try to use it.</p></div><h3 id="withjsonpsupport" tabindex="-1"><code>withJsonpSupport()</code> <a class="header-anchor" href="#withjsonpsupport" aria-label="Permalink to &quot;`withJsonpSupport()`&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">JSONP is deprecated</p><p><code>withJsonpSupport</code>, <code>HttpClientJsonpModule</code>, and the <code>.jsonp()</code> method on <code>HttpClient</code> are deprecated because JSONP can cause cross-site scripting (XSS) vulnerabilities. Use standard HTTP requests with <a href="https://developer.mozilla.org/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a> instead.</p></div><p>Including <code>withJsonpSupport</code> enables the <code>.jsonp()</code> method on <code>HttpClient</code>, which makes a GET request via the <a href="https://en.wikipedia.org/wiki/JSONP" target="_blank" rel="noreferrer">JSONP convention</a> for cross-domain loading of data.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>Prefer using <a href="https://developer.mozilla.org/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a> to make cross-domain requests instead of JSONP when possible.</p></div><h3 id="withxsrfconfiguration" tabindex="-1"><code>withXsrfConfiguration(...)</code> <a class="header-anchor" href="#withxsrfconfiguration" aria-label="Permalink to &quot;`withXsrfConfiguration(...)`&quot;">​</a></h3><p>Including this option allows customization of <code>HttpClient</code>&#39;s built-in XSRF security functionality. See the <a href="/en/best-practices/security">security guide</a> for more information.</p><h3 id="withnoxsrfprotection" tabindex="-1"><code>withNoXsrfProtection()</code> <a class="header-anchor" href="#withnoxsrfprotection" aria-label="Permalink to &quot;`withNoXsrfProtection()`&quot;">​</a></h3><p>Including this option disables <code>HttpClient</code>&#39;s built-in XSRF security functionality. See the <a href="/en/best-practices/security">security guide</a> for more information.</p><h2 id="httpclientmodule-based-configuration" tabindex="-1"><code>HttpClientModule</code>-based configuration <a class="header-anchor" href="#httpclientmodule-based-configuration" aria-label="Permalink to &quot;`HttpClientModule`-based configuration&quot;">​</a></h2><p>Some applications may configure <code>HttpClient</code> using the older API based on NgModules.</p><p>This table lists the NgModules available from <code>@angular/common/http</code> and how they relate to the provider configuration functions above.</p><table tabindex="0"><thead><tr><th><strong>NgModule</strong></th><th><code>provideHttpClient()</code> equivalent</th></tr></thead><tbody><tr><td><code>HttpClientModule</code></td><td><code>provideHttpClient(withInterceptorsFromDi(), withXhr())</code></td></tr><tr><td><code>HttpClientJsonpModule</code> (deprecated)</td><td><code>withJsonpSupport()</code> (deprecated)</td></tr><tr><td><code>HttpClientXsrfModule.withOptions(...)</code></td><td><code>withXsrfConfiguration(...)</code></td></tr><tr><td><code>HttpClientXsrfModule.disable()</code></td><td><code>withNoXsrfProtection()</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">NOTE</p><p><code>HttpClientModule</code> and <code>HttpClientXsrfModule</code> are also deprecated. Use <code>provideHttpClient</code> with the corresponding features instead.</p></div><div class="warning custom-block"><p class="custom-block-title">Use caution when using HttpClientModule in multiple injectors</p><p>When <code>HttpClientModule</code> is present in multiple injectors, the behavior of interceptors is poorly defined and depends on the exact options and provider/import ordering.</p><p>Prefer <code>provideHttpClient</code> for multi-injector configurations, as it has more stable behavior. See the <code>withRequestsMadeViaParent</code> feature above.</p></div>',39)]))}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
